INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'luxembourg','country','LU','Adult-Use Home Cultivation Legal; Medical Legal',
'Luxembourg became the first European country to fully legalize adult-use cannabis cultivation and possession for personal use in October 2023. Adults may cultivate up to four plants at home and possess up to three grams in public. Commercial adult-use sales remain prohibited pending further regulatory development. Luxembourg also has a medical cannabis program established in 2018, which provides pharmacy-dispensed products under physician prescription.',
'Medical cannabis patients access products through licensed pharmacies with physician prescription. The 2018 medical program covers conditions including multiple sclerosis, chronic pain, and cancer. Adults may also cultivate cannabis at home for personal use under the 2023 reform.',
'Luxembourg physicians may prescribe medical cannabis for qualifying conditions under the 2018 medical framework. General practitioners can prescribe with standard prescription procedures.',
'Luxembourg''s medical cannabis market is small given the country''s population of approximately 660,000. The 2023 home cultivation reform has not yet created commercial sales infrastructure. Interest in commercial adult-use framework development is high given Luxembourg''s role in EU policy signaling.',
'Luxembourg is expected to develop a commercial adult-use sales framework. As the first EU country to permit adult-use possession, Luxembourg''s policy development will be closely watched by EU institutions and member states. Commercial framework details are anticipated over 2025–2027.',
'Direction de la Santé (Health Directorate) regulates medical cannabis products. Ministry of Health sets health policy. Ministère de la Justice oversees drug law enforcement.',
'Luxembourg Law of 19 February 2018 (medical); Law of 8 June 2023 (adult-use home cultivation); Direction de la Santé regulatory guidance; EMCDDA Luxembourg report','Current as of Q2 2026; verified against Direction de la Santé guidance','Quarterly','Country-level briefing covering first EU adult-use legalization (home cultivation) and medical program',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='LU' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'malta','country','MT','Adult-Use Legal (First Full EU Nation); Medical Legal',
'Malta became the first EU member state to legalize adult-use cannabis in December 2021 through the Authority on the Responsible Use of Cannabis Act (ARUCA). Adults may possess up to seven grams and cultivate up to four plants at home. Cannabis clubs (non-profit associations) are licensed to cultivate and distribute to members. Malta also has an existing medical cannabis program established in 2018. Commercial adult-use retail has not been implemented.',
'Patients access medical cannabis through licensed pharmacies with physician prescription under the 2018 medical program. Adults may also access cannabis through non-profit cannabis clubs under ARUCA. The club model requires membership and operates under ARUCA licensing.',
'Maltese physicians may prescribe medical cannabis for qualifying conditions under the 2018 medical framework. ARUCA''s club model also provides a non-medical adult-use pathway.',
'Malta''s cannabis club model has developed slowly since ARUCA''s passage. A small number of clubs have received licenses. The medical cannabis market continues to operate in parallel. Malta''s small size (approximately 500,000 population) limits overall market scale.',
'Malta continues to develop the ARUCA regulatory framework and cannabis club infrastructure. Its role as the first EU nation with full adult-use legislation — even without commercial retail — makes Malta an important EU policy reference. Commercial retail remains under consideration.',
'Authority on the Responsible Use of Cannabis (ARUCA) administers the adult-use framework. Medicines Authority regulates medical cannabis products. Ministry of Health sets health policy.',
'ARUCA Act 2021; Medicines Authority medical cannabis framework; ARUCA annual reports; EMCDDA Malta report','Current as of Q2 2026; verified against ARUCA and Medicines Authority guidance','Quarterly','Country-level briefing covering landmark first-EU adult-use legalization and dual medical/adult-use framework',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='MT' AND jurisdiction_type='country');

