INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'norway','country','NO','Prohibited; Reform Debate',
'Cannabis is prohibited in Norway under the Narcotic Drugs Act. Norway is not an EU member but participates in the European Economic Area, creating some policy alignment. A significant drug reform proposal moving toward decriminalization was debated in the Storting (Parliament) and ultimately rejected in 2021, but reform advocacy continues. There is no formal medical cannabis program, though some named-patient access exists for specific pharmaceutical products.',
'Limited named-patient access exists for specific cannabis-derived pharmaceuticals under exceptional circumstances with approval from the Norwegian Medicines Agency. No systematic medical cannabis program exists.',
'Norwegian physicians may apply for named-patient authorization for specific cannabis-derived pharmaceuticals in exceptional cases. The process is administratively demanding.',
'No licensed cannabis market exists. Norway''s welfare-state model and harm-reduction public health approach create ongoing policy tension between enforcement and treatment.',
'Drug policy reform remains debated in Norway. The failed 2021 decriminalization vote may be revisited in future Storting sessions. Medical cannabis framework development is possible over 2025–2028 as European norms evolve.',
'Norwegian Police Directorate handles drug enforcement. Norwegian Medicines Agency (Statens legemiddelverk) oversees pharmaceutical regulation.',
'Norway Narcotic Drugs Act; Statens legemiddelverk named-patient authorization data; Storting drug reform debates; EMCDDA Norway report','Current as of Q2 2026','Annual','Country-level briefing noting prohibition with ongoing reform debate',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='NO' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'poland','country','PL','Medical Legal',
'Poland legalized medical cannabis in November 2017 through an amendment to the Act on Counteracting Drug Addiction. The program permits the prescription of cannabis flower, extract, and oil for medical purposes. Poland''s large population (approximately 38 million) makes it one of Europe''s most significant potential medical cannabis markets. Patient access has grown considerably since the program launched.',
'Polish patients access medical cannabis through licensed pharmacies (apteki) with a physician prescription (recepta). Products include cannabis flower (suszone kwiatostany) and oil preparations. Both imported products and domestically produced items are available. Out-of-pocket costs apply as NFZ (national health insurance) reimbursement is limited to specific indications.',
'Polish physicians (lekarze) may prescribe medical cannabis for a wide range of conditions without formal specialty restrictions. The Polish Chamber of Physicians has issued guidance on evidence-based prescribing. General practitioners can prescribe; specialist involvement is common for complex conditions.',
'Poland has developed a substantial medical cannabis market. Domestic cultivation and production licenses have been issued to multiple operators. International cannabis companies including Canadian and Dutch LPs have established Polish market presence. Patient numbers are estimated in the hundreds of thousands.',
'Poland''s medical cannabis market is one of Europe''s fastest-growing given population scale. Further domestic production capacity expansion is expected. Adult-use legalization is discussed but not imminent under current political dynamics.',
'Główny Inspektorat Farmaceutyczny (GIF/Chief Pharmaceutical Inspectorate) regulates medical cannabis products. Ministry of Health sets clinical guidelines.',
'Polish Act on Counteracting Drug Addiction 2017 amendment; GIF regulatory guidance and licensed product database; Ministry of Health clinical guidelines; EMCDDA Poland report','Current as of Q2 2026; verified against GIF official guidance','Quarterly','Country-level briefing covering substantial medical program and large patient population',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='PL' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'portugal','country','PT','Decriminalized; Medical Legal; Export Licensed',
'Portugal''s 2001 drug decriminalization reform (Law 30/2000) remains one of the world''s most significant drug policy innovations — all personal use drugs are decriminalized, with users referred to Dissuasion Commissions rather than criminal courts. Medical cannabis was legalized in 2018 (Decree-Law 8/2019) with a full licensing framework for cultivation, processing, and export. Portugal has become a significant European medical cannabis production and export hub.',
'Patients access medical cannabis through licensed pharmacies with physician prescription. Both Portuguese-produced and imported products are available. INFARMED maintains an approved product list. Social security reimbursement is under development for specific conditions. Patient numbers have grown substantially since 2019.',
'Portuguese physicians (médicos) may prescribe authorized medical cannabis products for conditions including multiple sclerosis, chronic pain, and nausea. General practitioners can prescribe; specialist endorsement is common for complex conditions. The Ordem dos Médicos has issued prescribing guidance.',
'Portugal has become a major European medical cannabis production hub. Multiple licensed operators cultivate and process cannabis in Portugal, with significant export to Germany, UK, and other European markets. Portuguese production benefits from climate, agricultural expertise, and relatively streamlined licensing compared to some competitors.',
'Portugal''s medical cannabis export sector is expected to continue growing as European demand increases. Regulatory refinements supporting larger-scale production and export are anticipated. The country''s decriminalization framework is well-established and not under political threat.',
'INFARMED (Autoridade Nacional do Medicamento e Produtos de Saúde) regulates medical cannabis products and licensing. ASAE (Autoridade de Segurança Alimentar e Económica) handles CBD food supplement oversight.',
'Portugal Decree-Law 8/2019; INFARMED regulatory guidance and licensed product database; Law 30/2000 decriminalization framework; EMCDDA Portugal report','Current as of Q2 2026; verified against INFARMED official guidance','Quarterly','Full country-level briefing covering decriminalization legacy, medical program, and export hub development',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='PT' AND jurisdiction_type='country');

