INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'serbia','country','RS','Medical Legal; Export Development',
'Serbia legalized medical cannabis in 2019 through amendments to the Law on Psychoactive Controlled Substances. The program permits licensed cultivation, processing, and prescription of medical cannabis products. Serbia has actively developed an export-oriented cannabis production sector. Its position outside the EU provides some regulatory flexibility while its EU accession candidacy creates harmonization incentives.',
'Patients access medical cannabis through licensed pharmacies with physician prescription. Both domestically produced and imported products are available. Limited health insurance coverage exists. Patient registration is required for some product categories.',
'Serbian physicians may prescribe medical cannabis for qualifying conditions including multiple sclerosis, chronic pain, and epilepsy. Specialist recommendation is typically required for complex conditions.',
'Serbia has developed a licensed medical cannabis cultivation and processing industry with export orientation. Several licensed operators produce for European markets. The country''s competitive production costs and agricultural infrastructure make it an attractive production location.',
'Serbia''s medical cannabis export sector is expected to grow. EU accession aspirations will drive further regulatory harmonization. The country positions itself competitively with North Macedonia and other Western Balkan producers.',
'Agency for Medicines and Medical Devices of Serbia (ALIMS) regulates medical cannabis. Ministry of Agriculture oversees cultivation licensing.',
'Serbia Law on Psychoactive Controlled Substances 2019 amendment; ALIMS regulatory guidance; Ministry of Agriculture cultivation data; EU accession monitoring','Current as of Q2 2026','Quarterly','Country-level briefing covering medical program and export-oriented production sector',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='RS' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'slovakia','country','SK','Prohibited; CBD Gray Area',
'Cannabis is prohibited in Slovakia under the Act on Combating Drug Addiction. Slovakia has one of Central Europe''s stricter drug enforcement postures, with no decriminalization framework for personal use. There is no medical cannabis program. CBD products are commercially available but exist in legal uncertainty. Slovakia has not aligned with neighboring Czech Republic''s more progressive approach.',
'No legal patient access to medical cannabis exists. Cannabis-based pharmaceuticals are not available through official Slovak healthcare channels.',
'Slovak physicians cannot prescribe cannabis under the existing legal framework.',
'No licensed cannabis market exists. The CBD sector operates under regulatory uncertainty. Slovakia''s neighboring Czech Republic''s more progressive framework creates cross-border market dynamics.',
'EU membership may eventually drive medical cannabis harmonization. No imminent legislative action is expected under current governance.',
'Slovak Police handles drug enforcement. State Institute for Drug Control (ŠÚKL) oversees pharmaceutical regulation.',
'Slovakia Act on Combating Drug Addiction; ŠÚKL pharmaceutical registry; EMCDDA Slovakia report','Current as of Q2 2026','Annual','Country-level briefing noting strict prohibition in EU context',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='SK' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'slovenia','country','SI','Medical Legal; Decriminalized',
'Slovenia has a medical cannabis framework established under pharmaceutical regulations permitting named-patient access to cannabis-based medicines. Personal possession of small amounts is decriminalized (administrative fine). Slovenia''s healthcare system has integrated medical cannabis prescribing within standard pharmaceutical dispensing channels. CBD products with low THC are commercially available.',
'Patients access medical cannabis through licensed pharmacies with physician prescription. Named-patient authorization may be required for certain preparations. Both imported and pharmacy-compounded preparations are available. Limited social insurance reimbursement exists for specific indications.',
'Slovenian physicians may prescribe medical cannabis for qualifying conditions including chronic pain, multiple sclerosis, and cancer-related symptoms. General practitioners can prescribe standard approved preparations.',
'Slovenia has a small, functional medical cannabis market. Products are primarily imported with some pharmacy magistral preparations. The market serves a growing patient base benefiting from increasingly common prescribing.',
'Slovenia may develop more structured medical cannabis licensing as EU harmonization progresses. The decriminalization framework is well-established and the medical program continues to grow.',
'Javna agencija Republike Slovenije za zdravila in medicinske pripomočke (JAZMP) regulates medical cannabis products. Ministry of Health sets clinical guidelines.',
'JAZMP pharmaceutical registry; Slovenian decriminalization framework; Ministry of Health clinical guidelines; EMCDDA Slovenia report','Current as of Q2 2026','Annual','Country-level briefing covering medical access and decriminalization',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='SI' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'sweden','country','SE','Prohibited; Strict Enforcement; Epidiolex Available',
'Sweden maintains strict cannabis prohibition under the Narcotic Drugs Punishments Act. Sweden''s drug policy is among the most enforcement-focused in the EU, with even personal possession subject to criminal prosecution. Sweden has not implemented decriminalization. Epidiolex (CBD for epilepsy) has received Swedish Medical Products Agency approval for specific epilepsy indications. The political debate over cannabis policy has been intense, with law enforcement and public health perspectives dominating.',
'No general medical cannabis access exists. Epidiolex (cannabidiol) is approved by Läkemedelsverket for treatment of seizures associated with Lennox-Gastaut syndrome and Dravet syndrome, available through specialist prescription. No broader cannabis medicine access pathway exists.',
'Swedish physicians may prescribe Epidiolex for approved epilepsy indications through specialist (neurologist/epileptologist) prescription. No other cannabis-based medicines are accessible through standard Swedish prescribing channels.',
'The Swedish medical cannabis market is extremely limited, restricted to Epidiolex for specific epilepsy conditions. No broader licensed cannabis market exists. Sweden''s strict enforcement framework effectively limits any informal commercial activity.',
'Sweden''s drug policy trajectory remains enforcement-focused. Medical expansion beyond Epidiolex is possible if EU harmonization creates pressure, but the political environment resists liberalization. A change in governing coalition could shift the trajectory.',
'Läkemedelsverket (Swedish Medical Products Agency/LMV) regulates pharmaceutical products. National Police Authority handles drug enforcement.',
'Sweden Narcotic Drugs Punishments Act; Läkemedelsverket pharmaceutical registry; Epidiolex approval data; EMCDDA Sweden report','Current as of Q2 2026; verified against Läkemedelsverket official guidance','Annual','Country-level briefing noting strict prohibition with limited Epidiolex pharmaceutical access',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='SE' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'switzerland','country','CH','Adult-Use Pilot Programs; Medical Legal; CBD Legal',
'Switzerland has developed one of Europe''s most progressive cannabis frameworks. CBD cannabis with THC below 1% (Switzerland uses a 1% threshold vs. the EU''s 0.2%) has been legally sold since 2016. Medical cannabis became accessible through licensed pharmacies with physician prescription in 2022 following regulatory reform. From 2023, Switzerland launched regulated adult-use pilot programs in several cities (Basel, Bern, Geneva, Zurich) under the Federal Act on Research into the Regulated Cannabis Market (Experimentiergesetz), allowing up to 21,000 adult participants to access cannabis through cannabis social clubs, pharmacies, and specialized shops.',
'Patients access medical cannabis through licensed pharmacies with physician prescription. CBD products are widely available commercially. Adults participating in pilot programs can access cannabis through designated distribution points. The pilot programs are research-linked and require participant registration.',
'Swiss physicians (Ärzte/médecins) may prescribe medical cannabis for a wide range of conditions without specialist restriction. Prescription requires standard physician documentation. CBD products are accessible without prescription given their legal consumer goods status.',
'Switzerland has a vibrant CBD cannabis market (one of the world''s largest per capita). The medical cannabis market is growing rapidly following 2022 regulatory reform. The adult-use pilot programs provide a unique regulated access model being studied globally. Multiple Swiss companies operate in cultivation, processing, and retail.',
'Switzerland''s pilot program results will inform potential full adult-use legalization. Voter initiatives for full legalization are expected. The pilot program framework is expected to expand to additional cities. Switzerland''s innovation in regulated access serves as a European reference model.',
'Swissmedic regulates pharmaceutical-grade medical cannabis. BAZG (Federal Office for Customs and Border Security) handles CBD cannabis import/export. FOPH (Federal Office of Public Health) oversees pilot program authorization.',
'Swiss Federal Act on Narcotics; 2022 medical cannabis regulatory reform; Federal Act on Research into Regulated Cannabis Market (Experimentiergesetz); Swissmedic guidance; FOPH pilot program reports','Current as of Q2 2026; verified against Swissmedic and FOPH guidance','Quarterly','Full country-level briefing covering CBD market, medical program, and adult-use pilot programs',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='CH' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'turkey','country','TR','Medical Legal (Industrial Hemp Focus); No Adult-Use',
'Turkey legalized medical cannabis cultivation through regulatory amendments in 2016 and expanded the framework through subsequent legislation. Turkey has historically been a significant producer of opium for pharmaceutical purposes (under INCB oversight) and has applied similar state-supervised approaches to cannabis. Industrial hemp cultivation is licensed in multiple provinces. Medical cannabis products including Sativex are available through prescription in the Turkish healthcare system.',
'Patients access approved cannabis-based medicines (including Sativex) through licensed pharmacies with physician prescription. Products must be registered with TITCK. Patient access is limited by product availability and cost.',
'Turkish physicians registered with the Turkish Medical Association may prescribe approved cannabis-based medicines for qualifying conditions including multiple sclerosis spasticity. Specialist (neurologist) prescription is expected for most indications.',
'Turkey has a significant licensed hemp cultivation sector with state oversight through TAPDK. Medical cannabis product access is limited to TITCK-approved products. Turkey''s pharmaceutical manufacturing infrastructure creates potential for domestic medical cannabis product development.',
'Turkey''s medical cannabis framework may expand as TITCK approves additional products. Industrial hemp policy is expected to continue developing. Turkey''s geographic position between European and Middle Eastern markets creates unique commercial opportunities.',
'Türkiye İlaç ve Tıbbi Cihaz Kurumu (TITCK/Turkish Medicines and Medical Devices Agency) regulates cannabis medicines. TAPDK (Tobacco and Alcohol Market Regulatory Authority) oversees hemp cultivation licensing.',
'TITCK pharmaceutical registry; TAPDK hemp cultivation license data; Turkish Medical Association prescribing guidelines; Turkey hemp agriculture statistics','Current as of Q2 2026; verified against TITCK official guidance','Quarterly','Country-level briefing covering medical program and industrial hemp sector',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='TR' AND jurisdiction_type='country');

INSERT INTO cc_jurisdiction_briefings (jurisdiction_slug,jurisdiction_type,country_iso2,program_status,public_summary,patient_access,physician_access,market_dynamics,regulatory_outlook,regulatory_body,data_source_summary,verification_summary,update_cadence,coverage_summary,last_reviewed_date,watch_regions,change_notes,review_state)
SELECT 'ukraine','country','UA','Prohibited; Wartime Context; Medical Reform Pending',
'Cannabis is prohibited in Ukraine under the Law on Narcotic Drugs, Psychotropic Substances, Precursors and Combating Their Illicit Trafficking. Ukraine''s ongoing war with Russia (since February 2022) has created a significant policy discussion around medical cannabis access for war veterans and civilian trauma patients. Medical cannabis legalization legislation has been advanced through the Verkhovna Rada as a wartime healthcare priority, reflecting growing international evidence of cannabis''s utility for PTSD and pain management.',
'No formal patient access to medical cannabis exists under current law. The pending medical cannabis legislation, if enacted, would create a physician-prescription pathway primarily focused on trauma and PTSD indications. Access during the conflict period remains under the current prohibition framework.',
'Ukrainian physicians cannot currently prescribe cannabis. If the pending legislation passes, physician prescribing authority for trauma, PTSD, and chronic pain indications is proposed.',
'No licensed cannabis market exists. Post-war reconstruction may create significant demand for pain management and mental health treatments if medical cannabis access is established. Ukraine''s agricultural capacity would allow rapid domestic production development.',
'Ukraine''s medical cannabis legislation has been actively debated and has achieved parliamentary support in multiple readings. Full legalization for medical purposes, particularly for war veterans, is anticipated in 2026. Rapid implementation following legislation is expected given wartime healthcare urgency.',
'Ministry of Health of Ukraine oversees pharmaceutical regulation. Medical cannabis reform is advancing through the Verkhovna Rada Health Committee.',
'Ukraine Law on Narcotic Drugs; Verkhovna Rada medical cannabis bill status; Ministry of Health policy documents; WHO Ukraine health system reports','Current as of Q2 2026; monitoring wartime legislation progress','Quarterly','Country-level briefing covering wartime medical cannabis legalization progress and veteran access priority',DATE '2026-06-21','[]'::jsonb,'[]'::jsonb,'reviewed'
WHERE NOT EXISTS (SELECT 1 FROM cc_jurisdiction_briefings WHERE country_iso2='UA' AND jurisdiction_type='country');

